      if (v.includes('combo')) return "Maryland CCW & HQL Combo";
      if (v.includes('renewal') || v.includes('recertification') || v.includes('8-hour') || v.includes('8 hour')) return "Maryland Wear & Carry (8-Hour Renewal)";
